head.script:
// 팝업 레이어 생성 함수
scwin.createPopupLayer = function () {

    var existingPopup = document.getElementById('customAlertPopup');
    if (existingPopup) {
        existingPopup.remove();
    }

    var popupHtml = `
        <div id="customAlertPopup" style="
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0,0,0,0.5);
            z-index: 9999;
            display: none;
        ">
            <div style="
                position: absolute;
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%);
                background: white;
                padding: 30px;
                border-radius: 8px;
                box-shadow: 0 4px 20px rgba(0,0,0,0.3);
                min-width: 350px;
                max-width: 500px;
                text-align: center;
            ">
                <div id="popupMessage" style="
                    margin-bottom: 25px; 
                    font-size: 15px; 
                    line-height: 1.5;
                    color: #333;
                    white-space: pre-wrap;
                "></div>
                <div>
                    <button id="popupConfirm" style="
                        background: #007bff;
                        color: white;
                        border: none;
                        padding: 10px 20px;
                        margin: 0 5px;
                        border-radius: 4px;
                        cursor: pointer;
                        font-size: 14px;
                        min-width: 60px;
                    ">확인</button>
                    <button id="popupCancel" style="
                        background: #6c757d;
                        color: white;
                        border: none;
                        padding: 10px 20px;
                        margin: 0 5px;
                        border-radius: 4px;
                        cursor: pointer;
                        font-size: 14px;
                        min-width: 60px;
                    ">취소</button>
                </div>
            </div>
        </div>
    `;

    document.body.insertAdjacentHTML('beforeend', popupHtml);
};

// 팝업 표시 함수
scwin.showPopup = function (message, isConfirm, callback) {
    // 팝업 요소가 없으면 다시 생성
    var popup = document.getElementById('customAlertPopup');
    if (!popup) {
        console.log("팝업이 없어서 다시 생성합니다.");
        scwin.createPopupLayer();
        popup = document.getElementById('customAlertPopup');
    }

    var messageEl = document.getElementById('popupMessage');
    var confirmBtn = document.getElementById('popupConfirm');
    var cancelBtn = document.getElementById('popupCancel');

    // 안전성 검사
    if (!popup || !messageEl || !confirmBtn || !cancelBtn) {
        console.error("팝업 요소를 찾을 수 없습니다. 기본 alert 사용");
        alert(message);
        if (callback && !isConfirm) callback();
        return;
    }

    messageEl.textContent = message;

    if (isConfirm) {
        cancelBtn.style.display = 'inline-block';
        confirmBtn.onclick = function () {
            popup.style.display = 'none';
            if (callback) callback(true);
        };
        cancelBtn.onclick = function () {
            popup.style.display = 'none';
            if (callback) callback(false);
        };
    } else {
        cancelBtn.style.display = 'none';
        confirmBtn.onclick = function () {
            popup.style.display = 'none';
            if (callback) callback();
        };
    }

    popup.style.display = 'block';
};

/**
 * @description 기존 WebSquare 알림창 대신 커스텀 팝업을 사용
 * @param {String} message 표시할 메시지
 * @param {String} type 메시지 종류 ('success', 'error', 'warning', 'info') - 호환성을 위해 유지하되 사용하지 않음
 */
scwin.showAlert = function (message, type) {
    // 기존 코드와의 호환성을 위해 scwin.showPopup 호출
    scwin.showPopup(message);
};

scwin.onpageload = function () {
    console.log("출석 모듈 페이지 로드 시작");

    // 1. 팝업 레이어 초기화 (가장 먼저)
    scwin.createPopupLayer();
    console.log("팝업 레이어 초기화 완료");

    // 2. 통계 초기값 설정
    dm_stats.setJSON({ totalCount: "0", activeCount: "0", leftCount: "0", avgMinutes: "0" });

    // 3. 페이지 로드 시 드롭다운 초기화
    dlt_dynamicSessionList.setJSON([{ session_id: "", session_name: "전체" }]);

    // 4. 초기 검색 조건 설정 - 전체 데이터 조회
    dm_search.set("scSessionId", "");
    dm_search.set("scName", "");
    dm_search.set("scEmail", "");
    dm_search.set("scJoinTime", "");
    dm_search.set("pageSize", "100");
    dm_search.set("pageIndex", "1");
    dm_search.set("sortOrder", "DESC");

    // 5. 페이지 로드 시, 전체 데이터 조회
    scwin.btn_search_onclick();

    console.log("출석 모듈 페이지 로드 완료");
};

scwin.onpageload = function () {
    // 통계 초기값 설정
    dm_stats.setJSON({ totalCount: "0", activeCount: "0", leftCount: "0", avgMinutes: "0" });

    // 페이지 로드 시 드롭다운 초기화
    dlt_dynamicSessionList.setJSON([{ session_id: "", session_name: "전체" }]);

    // 초기 검색 조건 설정 - 전체 데이터 조회
    dm_search.set("scSessionId", "");
    dm_search.set("scName", "");
    dm_search.set("scEmail", "");
    dm_search.set("scJoinTime", "");
    dm_search.set("pageSize", "100");
    dm_search.set("pageIndex", "1");
    dm_search.set("sortOrder", "DESC");


    // 페이지 로드 시, 전체 데이터 조회
    scwin.btn_search_onclick();

};

// 새로고침 시에도 전체 데이터 조회
scwin.btn_refresh_onclick = function () {
    console.log("새로고침 - 전체 데이터 조회");

    // 검색 조건 초기화 (전체 조회)
    dm_search.setJSON({
        scSessionId: "",
        scName: "",
        scEmail: "",
        scJoinTime: "",
        pageSize: "100",    // 전체 데이터 조회용 큰 값
        pageIndex: "1"
    });

    // 선택박스도 초기화
    if (typeof sel_sessionId !== 'undefined') {
        sel_sessionId.value = "";
    }

    scwin.btn_search_onclick('refresh');
};

/**
 * @description 검색 버튼 클릭 시 호출됩니다.
 * 여러 방법을 시도하여 안정적으로 데이터를 조회합니다.
 */
scwin.btn_search_onclick = function () {

    dm_search.set("scSessionId", sel_sessionId.getValue());
    dm_search.set("scName", ipt_searchName.getValue());
    dm_search.set("scEmail", ipt_searchEmail.getValue());
    dm_search.set("scJoinTime", ipt_searchDate.getValue());

    // 페이징 초기화
    dm_search.set("pageIndex", "1");

    scwin.jqueryAjaxCall();
};

/**
 * @description 정렬 버튼 클릭 시 호출됩니다.
 */
scwin.setSortOrder_onclick = function (order) {
    dm_search.set("sortOrder", order); // 정렬 순서 설정
    scwin.btn_search_onclick(); // 설정된 순서로 다시 검색
};

/**
 * @description Ajax 성공 응답을 처리합니다. (팝업 적용)
 */
scwin.handleSuccessResponse = function (responseData) {
    try {
        var attendanceVoList = null;

        if (responseData && responseData.elData && responseData.elData.attendanceVoList) {
            attendanceVoList = responseData.elData.attendanceVoList;
        }
        else if (responseData && responseData.attendanceListVo && responseData.attendanceListVo.attendanceVoList) {
            attendanceVoList = responseData.attendanceListVo.attendanceVoList;
        } else if (responseData && responseData.attendanceVoList) {
            attendanceVoList = responseData.attendanceVoList;
        } else if (responseData && responseData.elHeader && responseData.elHeader.responseData && responseData.elHeader.responseData.attendanceVoList) {
            attendanceVoList = responseData.elHeader.responseData.attendanceVoList;
        } else if (responseData && responseData.data && responseData.data.attendanceVoList) {
            attendanceVoList = responseData.data.attendanceVoList;
        } else {
            attendanceVoList = [];
        }

        if (attendanceVoList && attendanceVoList.length > 0) {
            // DataList에 데이터 설정
            attendanceList.setJSON(attendanceVoList);

            // 통계 업데이트
            scwin.updateStats(attendanceVoList);

            // 고유 세션 목록 생성 및 드롭다운 업데이트
            scwin.updateSessionDropdown(attendanceVoList);

        } else {
            attendanceList.removeAll();
            scwin.updateStats([]);
            // 커스텀 팝업으로 변경
            // scwin.showPopup("조회된 데이터가 없습니다.");
            scwin.updateSessionDropdown([]);
        }
    } catch (error) {
        console.error("응답 처리 중 오류:", error);
        attendanceList.removeAll();
        scwin.updateStats([]);
        scwin.showPopup("데이터 처리 중 오류가 발생했습니다: " + error.message);
    }
};

/**
 * @description 출석 목록을 기반으로 세션 드롭다운을 업데이트합니다.
 */
scwin.updateSessionDropdown = function (data) {
    // 1. 고유한 세션 ID를 추출하기 위해 Set을 사용
    const uniqueSessionIds = new Set(data.map(item => item.sessionId));

    // 2. dataList에 넣을 데이터 배열 생성
    const sessionListData = [
        // 기본값 '전체'를 가장 먼저 추가
        { session_id: "", session_name: "전체" }
    ];

    // 3. 고유 세션 ID들을 순회하며 dataList 형식에 맞게 추가
    uniqueSessionIds.forEach(id => {
        if (id) { // 세션 ID가 있는 경우에만 추가
            sessionListData.push({
                session_id: id,
                // 참고: attendanceList에는 세션 이름이 없으므로 ID를 이름으로 함께 사용합니다.
                session_name: id
            });
        }
    });

    // 4. 새로 만든 동적 세션 dataList에 데이터 설정
    dlt_dynamicSessionList.setJSON(sessionListData);
    console.log("세션 드롭다운이 업데이트되었습니다.", sessionListData);


};

/**
 * @description WebSquare Submission 완료 핸들러 (팝업 적용)
 */
scwin.sbm_searchAttendance_submitdone = function (e) {
    console.log("데이터 조회 성공:", e);

    try {
        var responseData = e.responseJSON;

        // 동일한 로직 적용
        var attendanceVoList = null;

        if (responseData && responseData.attendanceListVo && responseData.attendanceListVo.attendanceVoList) {
            attendanceVoList = responseData.attendanceListVo.attendanceVoList;
        } else if (responseData && responseData.attendanceVoList) {
            attendanceVoList = responseData.attendanceVoList;
        } else {
            console.warn("응답 데이터 형식이 올바르지 않습니다.", responseData);
            attendanceList.removeAll();
            scwin.updateStats([]);
            scwin.showPopup("서버로부터 받은 데이터가 올바르지 않습니다.");
            return;
        }

        if (attendanceVoList && attendanceVoList.length > 0) {
            // DataList에 데이터 설정
            attendanceList.setJSON(attendanceVoList);

            // 통계 업데이트
            scwin.updateStats(attendanceVoList);

            console.log("조회 완료: " + attendanceVoList.length + "건의 데이터가 조회되었습니다.");
        } else {
            console.log("조회된 데이터 없음");
            attendanceList.removeAll();
            scwin.updateStats([]);
            scwin.showPopup("조회된 데이터가 없습니다.");
        }
    } catch (error) {
        console.error("응답 처리 중 오류:", error);
        attendanceList.removeAll();
        scwin.updateStats([]);
        scwin.showPopup("데이터 처리 중 오류가 발생했습니다.");
    }
};


/**
 * @description 대안 Ajax 호출 방법 (팝업 적용)
 */
scwin.fallbackAjaxCall = function () {
    console.log("대안 Ajax 호출 시작");

    var searchData = dm_search.getJSON();
    console.log("전송할 검색 데이터:", JSON.stringify(searchData));

    var backendUrl = '/InsWebApp/AttendanceList.pwkjson';

    // WebSquare의 Ajax 호출 방식
    var option = {
        requestUri: backendUrl,
        requestType: "POST",
        dataType: "json",
        requestData: searchData,
        onSuccess: function (responseData) {
            scwin.handleSuccessResponse(responseData);
        },
        onError: function (xhr, status, error) {
            console.error("백엔드 연결 실패:", "상태:", xhr.status, "오류:", error);
            scwin.showPopup("서버에서 데이터를 가져오는 데 실패했습니다. 잠시 후 다시 시도해주세요.\n(오류: " + xhr.status + ")");
            attendanceList.removeAll();
            scwin.updateStats([]);
        }
    };

    $p.requestData(option);
};


/**
 * @description jQuery Ajax를 사용한 대안 방법 (팝업 적용)
 */
scwin.jqueryAjaxCall = function () {
    var searchData = dm_search.getJSON();

    // 1. 컨트롤러 메소드의 파라미터 이름('attendanceVo')을 키로 사용하는 새로운 payload 객체를 생성합니다.
    var payload = {
        attendanceVo: searchData
    };

    console.log("전송할 최종 Payload:", JSON.stringify(payload)); // 디버깅을 위한 로그 추가

    var backendUrl = '/InsWebApp/AttendanceList.pwkjson';

    $.ajax({
        url: backendUrl,
        type: 'POST',
        contentType: 'application/json; charset=utf-8',
        // 2. searchData 대신 새로운 payload 객체를 전송합니다.
        data: JSON.stringify(payload),
        timeout: 10000,
        success: function (responseData) {
            scwin.handleSuccessResponse(responseData);
        },
        error: function (xhr, status, error) {
            scwin.showPopup("서버에서 데이터를 가져오는 데 실패했습니다. 잠시 후 다시 시도해주세요.\n(오류: " + xhr.status + ")");
            attendanceList.removeAll();
            scwin.updateStats([]);
        }
    });
};

scwin.sbm_searchAttendance_submiterror = function (e) {
    console.error("데이터 조회 실패:", e);

    var errorMsg = "서버에서 데이터를 가져오는 데 실패했습니다.";

    if (e.errorType) {
        errorMsg += "\n오류 유형: " + e.errorType;
    }
    if (e.responseText) {
        errorMsg += "\n상세 오류: " + e.responseText;
    }

    scwin.showPopup(errorMsg);

    // 실패 시 그리드와 통계 초기화
    attendanceList.removeAll();
    scwin.updateStats([]);
};


/**
 * @description 워크플로우 처리 함수 (팝업 적용)
 */
scwin.wf_searchAttendance_onprocess = function (e) {
    if (e.errorType) {
        scwin.showPopup("데이터 조회 중 오류가 발생했습니다: " + e.errorType);
        return;
    }

    var responseData = e.responseData;
    if (responseData && responseData.attendanceVoList) {
        attendanceList.setJSON(responseData.attendanceVoList);
        scwin.updateStats(responseData.attendanceVoList);
    }
};

/**
 * @description 데이터 목록을 기반으로 통계 정보를 업데이트합니다.
 */
scwin.updateStats = function (data) {
    var total = data.length;
    var active = 0;
    var totalMinutes = 0;
    var validCount = 0;

    for (var i = 0; i < data.length; i++) {
        var item = data[i];
        if (item.status === "참여중") {
            active++;
        }
        if (item.participationMinutes && !isNaN(item.participationMinutes)) {
            totalMinutes += parseInt(item.participationMinutes, 10);
            validCount++;
        }
    }

    var left = total - active;
    var avgMinutes = validCount > 0 ? Math.round(totalMinutes / validCount) : 0;

    dm_stats.set("totalCount", total);
    dm_stats.set("activeCount", active);
    dm_stats.set("leftCount", left);
    dm_stats.set("avgMinutes", avgMinutes);

    console.log("통계 업데이트 완료 - 총:", total, "참여중:", active, "퇴장:", left, "평균:", avgMinutes);
};

/**
 * @description 페이징 정보를 업데이트합니다.
 */
scwin.updatePaging = function (totalCount, currentPage, pageSize) {
    var totalPages = Math.ceil(totalCount / pageSize);
    var startNo = (currentPage - 1) * pageSize + 1;
    var endNo = Math.min(currentPage * pageSize, totalCount);

    dm_paging.set("totalCount", totalCount);
    dm_paging.set("currentPage", currentPage);
    dm_paging.set("totalPages", totalPages);
    dm_paging.set("pageSize", pageSize);
    dm_paging.set("startNo", startNo);
    dm_paging.set("endNo", endNo);

    console.log("페이징 정보 업데이트:", {
        total: totalCount,
        current: currentPage,
        totalPages: totalPages,
        startNo: startNo,
        endNo: endNo
    });
};

// 페이징 버튼 이벤트 함수들
scwin.goToFirstPage = function () {
    dm_search.set("pageIndex", "1");
    scwin.btn_search_onclick();
};

scwin.goToPrevPage = function () {
    var currentPage = parseInt(dm_search.get("pageIndex")) || 1;
    if (currentPage > 1) {
        dm_search.set("pageIndex", (currentPage - 1).toString());
        scwin.btn_search_onclick();
    }
};

scwin.goToNextPage = function () {
    var currentPage = parseInt(dm_search.get("pageIndex")) || 1;
    var totalPages = parseInt(dm_paging.get("totalPages")) || 1;
    if (currentPage < totalPages) {
        dm_search.set("pageIndex", (currentPage + 1).toString());
        scwin.btn_search_onclick();
    }
};

scwin.goToLastPage = function () {
    var totalPages = dm_paging.get("totalPages") || "1";
    dm_search.set("pageIndex", totalPages);
    scwin.btn_search_onclick();
};

scwin.changePageSize = function () {
    dm_search.set("pageIndex", "1"); // 페이지 크기 변경 시 첫 페이지로
    scwin.btn_search_onclick();
};

/**
 * @description 페이징 정보를 업데이트합니다.
 */
scwin.updatePaging = function (totalCount, currentPage, pageSize) {
    var totalPages = Math.ceil(totalCount / pageSize);
    var startNo = (currentPage - 1) * pageSize + 1;
    var endNo = Math.min(currentPage * pageSize, totalCount);

    dm_paging.set("totalCount", totalCount);
    dm_paging.set("currentPage", currentPage);
    dm_paging.set("totalPages", totalPages);
    dm_paging.set("pageSize", pageSize);
    dm_paging.set("startNo", startNo);
    dm_paging.set("endNo", endNo);

    console.log("페이징 정보 업데이트:", {
        total: totalCount,
        current: currentPage,
        totalPages: totalPages,
        startNo: startNo,
        endNo: endNo
    });
};

// 페이징 버튼 이벤트 함수들
scwin.goToFirstPage = function () {
    dm_search.set("pageIndex", "1");
    scwin.btn_search_onclick();
};

scwin.goToPrevPage = function () {
    var currentPage = parseInt(dm_search.get("pageIndex")) || 1;
    if (currentPage > 1) {
        dm_search.set("pageIndex", (currentPage - 1).toString());
        scwin.btn_search_onclick();
    }
};

/**
 * @description CSV 다운로드 버튼 클릭 시 호출됩니다. (안전성 강화)
 */
scwin.btn_downloadCSV_onclick = function () {
    console.log("CSV 다운로드 버튼 클릭됨");

    if (attendanceList.getTotalRow() === 0) {
        scwin.showPopup("다운로드할 데이터가 없습니다.");
        return;
    }

    try {
        var data = attendanceList.getAllJSON();
        var csvContent = '\ufeff'; // UTF-8 BOM

        // Header
        csvContent += '번호,세션ID,참여자명,이메일,접속IP,입장시간,퇴장시간,참여시간(분),상태\n';

        // Body
        for (var i = 0; i < data.length; i++) {
            var row = data[i];
            csvContent += (i + 1) + ',';
            csvContent += '"' + (row.sessionId || '') + '",';
            csvContent += '"' + (row.name || '') + '",';
            csvContent += '"' + (row.email || '') + '",';
            csvContent += '"' + (row.ipAddress || '') + '",';
            csvContent += '"' + (row.joinTime || '') + '",';
            csvContent += '"' + (row.leaveTime || '진행중') + '",';
            csvContent += '"' + (row.participationMinutes || '-') + '",';
            csvContent += '"' + (row.status || '') + '"\n';
        }

        // Download
        var blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        var link = document.createElement('a');
        var url = URL.createObjectURL(blob);
        link.setAttribute('href', url);

        var sessionId = dm_search.get("scSessionId") || "전체";
        var now = new Date();
        var dateStr = now.getFullYear() + String(now.getMonth() + 1).padStart(2, '0') + String(now.getDate()).padStart(2, '0');

        link.setAttribute('download', '출석현황_' + sessionId + '_' + dateStr + '.csv');
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);

        // 다운로드 완료 알림
        scwin.showPopup("CSV 파일이 다운로드되었습니다.");

    } catch (error) {
        console.error("CSV 다운로드 중 오류:", error);
        scwin.showPopup("CSV 다운로드 중 오류가 발생했습니다: " + error.message);
    }
};


/**
 * @description 검색 조건을 초기화합니다. (팝업 적용 및 안전성 강화)
 */
scwin.btn_reset_onclick = function () {
    console.log("초기화 버튼 클릭됨");

    // 팝업이 준비되었는지 확인
    if (!document.getElementById('customAlertPopup')) {
        console.log("팝업이 없어서 다시 생성");
        scwin.createPopupLayer();
    }

    scwin.showPopup("검색 조건을 초기화하시겠습니까?", true, function (result) {
        if (result) {
            dm_search.setJSON({
                scSessionId: "",
                scName: "",
                scEmail: "",
                scJoinTime: "",
                pageSize: "999",
                pageIndex: "1"
            });

            // 입력 필드들도 초기화
            if (typeof sel_sessionId !== 'undefined') {
                sel_sessionId.setValue("");
            }
            if (typeof ipt_searchName !== 'undefined') {
                ipt_searchName.setValue("");
            }
            if (typeof ipt_searchEmail !== 'undefined') {
                ipt_searchEmail.setValue("");
            }
            if (typeof ipt_searchDate !== 'undefined') {
                ipt_searchDate.setValue("");
            }

            attendanceList.removeAll();
            scwin.updateStats([]);
            scwin.showPopup("검색 조건이 초기화되었습니다.");
        }
    });
};

/**
 * @description 세션 선택 변경 시 자동으로 데이터를 조회합니다.
 */
scwin.sel_sessionId_onchange = function () {
    scwin.btn_search_onclick();
};

/**
 * @description 새로고침 버튼 클릭
 */
scwin.btn_refresh_onclick = function () {
    scwin.btn_search_onclick();
};

/**
 * @description 그리드 행 클릭 이벤트 (선택사항)
 */
scwin.grd_oncellclick = function (row, col) {
    console.log("선택된 행:", row, "컬럼:", col);
    var selectedData = attendanceList.getRowJSON(row);
    console.log("선택된 데이터:", selectedData);
};
